AssistantMessageToolRequest(name='create', tool_call_id='tooluse_hR2q2Y9gG2Wz8zP0XMQ331', arguments={'file_text': "/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-primary: #1a1a2e;
  --color-accent: #e94560;
  --color-accent-dark: #c73652;
  --color-surface: #ffffff;
  --color-surface-alt: #f7f7f9;
  --color-border: #e8e8ec;
  --color-text: #1a1a2e;
  --color-text-muted: #6b7280;
  --color-text-inverse: #ffffff;
  --color-deal: #16a34a;
  --color-deal-bg: #dcfce7;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --shadow-lg: 0 12px 40px rgba(0,0,0,.14);
  --transition: 200ms ease;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --max-width: 1200px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* ===== SKIP LINK ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: .5rem 1rem;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ===== LAYOUT ===== */
.container {
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: 1.5rem;
}

section { padding-block: 5rem; }

/* ===== SECTION HEADER ===== */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.5rem;
}
.section-header__eyebrow {
  display: block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .4rem;
}
.section-header__title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -.02em;
}
.section-header__link {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
  transition: gap var(--transition);
}
.section-header__link:hover { gap: .6rem; }
.section-header__link svg { width: 16px; height: 16px; }

/* ===== TYPOGRAPHY UTILITIES ===== */
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 600;
  transition: background var(--transition), color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
}
.btn--primary {
  background: var(--color-accent);
  color: #fff;
}
.btn--primary:hover {
  background: var(--color-accent-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(233,69,96,.35);
}
.btn--outline {
  background: transparent;
  color: var(--color-text);
  border: 1.5px solid var(--color-border);
}
.btn--outline:hover {
  border-color: var(--color-text);
  background: var(--color-text);
  color: #fff;
}
.btn--ghost {
  background: rgba(255,255,255,.15);
  color: #fff;
  border: 1.5px solid rgba(255,255,255,.4);
  backdrop-filter: blur(6px);
}
.btn--ghost:hover {
  background: rgba(255,255,255,.25);
}
.btn--icon {
  width: 40px; height: 40px;
  padding: 0;
  border-radius: 50%;
  background: var(--color-surface);
  color: var(--color-text);
  box-shadow: var(--shadow-sm);
}
.btn--icon:hover {
  background: var(--color-accent);
  color: #fff;
  box-shadow: var(--shadow-md);
}
.btn--icon svg { width: 18px; height: 18px; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.9);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}
.nav {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 68px;
}
.nav__logo {
  font-size: 1.4rem;
  font-weight: 900;
  letter-spacing: -.04em;
  color: var(--color-primary);
  flex-shrink: 0;
}
.nav__logo span { color: var(--color-accent); }

.nav__links {
  display: flex;
  align-items: center;
  gap: 1.75rem;
  margin-left: auto;
}
.nav__link {
  font-size: .9rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition);
  position: relative;
}
.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0; right: 0;
  height: 2px;
  background: var(--color-accent);
  border-radius: 2px;
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav__link:hover { color: var(--color-text); }
.nav__link:hover::after { transform: scaleX(1); }
.nav__link:focus-visible { outline: 2px solid var(--color-accent); border-radius: 2px; }

.nav__search {
  position: relative;
  display: flex;
  align-items: center;
}
.nav__search-input {
  width: 220px;
  padding: .5rem 1rem .5rem 2.4rem;
  border: 1.5px solid var(--color-border);
  border-radius: 999px;
  font-family: inherit;
  font-size: .85rem;
  background: var(--color-surface-alt);
  color: var(--color-text);
  transition: border-color var(--transition), width var(--transition);
}
.nav__search-input:focus {
  outline: none;
  border-color: var(--color-accent);
  width: 260px;
  background: #fff;
}
.nav__search-icon {
  position: absolute;
  left: .75rem;
  color: var(--color-text-muted);
  pointer-events: none;
  width: 15px; height: 15px;
}

.nav__actions {
  display: flex;
  align-items: center;
  gap: .5rem;
}
.nav__cart-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: 50%;
  transition: background var(--transition);
  color: var(--color-text);
}
.nav__cart-btn:hover { background: var(--color-surface-alt); }
.nav__cart-btn:focus-visible { outline: 2px solid var(--color-accent); border-radius: 50%; }
.nav__cart-btn svg { width: 22px; height: 22px; }
.nav__cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--color-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.nav__mobile-toggle {
  display: none;
  padding: .5rem;
  border-radius: var(--radius-sm);
}
.nav__mobile-toggle svg { width: 22px; height: 22px; }
.nav__mobile-toggle:focus-visible { outline: 2px solid var(--color-accent); }

/* ===== ANNOUNCEMENT BAR ===== */
.announcement-bar {
  background: var(--color-primary);
  color: #fff;
  text-align: center;
  padding: .55rem 1rem;
  font-size: .8rem;
  font-weight: 500;
  letter-spacing: .02em;
}
.announcement-bar a { color: var(--color-accent); text-decoration: underline; }

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 80vh;
  display: grid;
  place-items: center;
  overflow: hidden;
  padding-block: 0;
}
.hero__bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
}
.hero__bg-pattern {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 20% 50%, rgba(233,69,96,.15) 0%, transparent 50%),
    radial-gradient(circle at 80% 20%, rgba(15,52,96,.6) 0%, transparent 50%);
}
.hero__content {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  padding-block: 6rem;
}
.hero__badge {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .35rem .85rem;
  background: rgba(233,69,96,.15);
  border: 1px solid rgba(233,69,96,.35);
  border-radius: 999px;
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: #f87171;
  margin-bottom: 1.5rem;
}
.hero__badge-dot {
  width: 6px; height: 6px;
  background: var(--color-accent);
  border-radius: 50%;
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .5; transform: scale(1.4); }
}
.hero__title {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 900;
  line-height: 1.07;
  letter-spacing: -.03em;
  color: #fff;
  margin-bottom: 1.25rem;
}
.hero__title em {
  font-style: normal;
  color: var(--color-accent);
}
.hero__subtitle {
  font-size: 1.1rem;
  color: rgba(255,255,255,.65);
  max-width: 440px;
  line-height: 1.7;
  margin-bottom: 2.25rem;
}
.hero__actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}
.hero__stats {
  display: flex;
  gap: 2rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,.12);
}
.hero__stat-value {
  display: block;
  font-size: 1.75rem;
  font-weight: 800;
  color: #fff;
  letter-spacing: -.03em;
  line-height: 1;
}
.hero__stat-label {
  font-size: .8rem;
  color: rgba(255,255,255,.5);
  margin-top: .25rem;
}

.hero__visual {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.hero__card-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1rem;
}
.hero__product-card {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  backdrop-filter: blur(8px);
  transition: transform var(--transition), background var(--transition);
}
.hero__product-card:first-child {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 1rem;
}
.hero__product-card:hover {
  transform: translateY(-3px);
  background: rgba(255,255,255,.11);
}
.hero__product-card-img {
  width: 60px; height: 60px;
  border-radius: var(--radius-sm);
  object-fit: cover;
  background: rgba(255,255,255,.1);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
}
.hero__product-card-name {
  font-size: .85rem;
  font-weight: 600;
  color: rgba(255,255,255,.9);
  margin-bottom: .2rem;
}
.hero__product-card-price {
  font-size: .95rem;
  font-weight: 800;
  color: #fff;
}
.hero__product-card-meta {
  font-size: .75rem;
  color: rgba(255,255,255,.5);
  margin-top: .1rem;
}

/* ===== CATEGORIES ===== */
.categories { background: var(--color-surface-alt); }
.categories__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 1rem;
}
.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .75rem;
  padding: 1.5rem 1rem;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  text-align: center;
}
.category-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.category-card:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}
.category-card__icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.6rem;
  background: var(--color-surface-alt);
  transition: background var(--transition);
}
.category-card:hover .category-card__icon { background: rgba(233,69,96,.1); }
.category-card__name {
  font-size: .85rem;
  font-weight: 600;
  color: var(--color-text);
}
.category-card__count {
  font-size: .75rem;
  color: var(--color-text-muted);
}

/* ===== PRODUCT CARDS ===== */
.products__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.product-card__image-wrap {
  position: relative;
  aspect-ratio: 4/3;
  background: var(--color-surface-alt);
  overflow: hidden;
}
.product-card__emoji {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  transition: transform 300ms ease;
}
.product-card:hover .product-card__emoji { transform: scale(1.1); }

.product-card__badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .25rem .6rem;
  border-radius: var(--radius-sm);
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.product-card__badge--new {
  background: var(--color-primary);
  color: #fff;
}
.product-card__badge--sale {
  background: var(--color-accent);
  color: #fff;
}
.product-card__badge--bestseller {
  background: #f59e0b;
  color: #fff;
}

.product-card__actions {
  position: absolute;
  top: .75rem;
  right: .75rem;
  display: flex;
  flex-direction: column;
  gap: .4rem;
  opacity: 0;
  transform: translateX(8px);
  transition: opacity var(--transition), transform var(--transition);
}
.product-card:hover .product-card__actions,
.product-card:focus-within .product-card__actions {
  opacity: 1;
  transform: translateX(0);
}

.product-card__body {
  padding: 1.1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: .4rem;
  flex: 1;
}
.product-card__category {
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--color-text-muted);
}
.product-card__name {
  font-size: .95rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.3;
}
.product-card__rating {
  display: flex;
  align-items: center;
  gap: .3rem;
  font-size: .78rem;
  color: var(--color-text-muted);
}
.product-card__stars { color: #f59e0b; letter-spacing: -.05em; }

.product-card__footer {
  padding: .9rem 1.25rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5rem;
  border-top: 1px solid var(--color-border);
  margin-top: auto;
}
.product-card__price-group { display: flex; flex-direction: column; }
.product-card__price {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--color-text);
  letter-spacing: -.02em;
}
.product-card__price-original {
  font-size: .8rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.product-card__add-btn {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  padding: .55rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .8rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition);
  white-space: nowrap;
}
.product-card__add-btn:hover {
  background: var(--color-accent);
  transform: translateY(-1px);
}
.product-card__add-btn:focus-visible { outline: 3px solid var(--color-accent); outline-offset: 2px; }
.product-card__add-btn svg { width: 15px; height: 15px; }

/* ===== DEALS ===== */
.deals { background: var(--color-primary); color: #fff; }
.deals .section-header__eyebrow { color: #f87171; }
.deals .section-header__title { color: #fff; }
.deals .section-header__link { color: #f87171; }

.deals__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}

.deal-card {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: background var(--transition), transform var(--transition);
}
.deal-card:hover {
  background: rgba(255,255,255,.1);
  transform: translateY(-4px);
}

.deal-card__image-wrap {
  aspect-ratio: 16/9;
  background: rgba(255,255,255,.05);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  position: relative;
}
.deal-card__discount {
  position: absolute;
  top: .75rem;
  right: .75rem;
  background: var(--color-accent);
  color: #fff;
  font-size: .8rem;
  font-weight: 800;
  padding: .25rem .6rem;
  border-radius: var(--radius-sm);
}

.deal-card__body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; gap: .5rem; }
.deal-card__name {
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
}
.deal-card__meta {
  font-size: .8rem;
  color: rgba(255,255,255,.5);
}
.deal-card__pricing {
  display: flex;
  align-items: baseline;
  gap: .6rem;
  margin-top: auto;
  padding-top: .75rem;
}
.deal-card__price-new {
  font-size: 1.4rem;
  font-weight: 900;
  color: #fff;
  letter-spacing: -.03em;
}
.deal-card__price-old {
  font-size: .9rem;
  color: rgba(255,255,255,.4);
  text-decoration: line-through;
}
.deal-card__savings {
  font-size: .75rem;
  font-weight: 700;
  color: #4ade80;
  margin-left: auto;
}

.deal-card__timer {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.25rem;
  border-top: 1px solid rgba(255,255,255,.08);
  font-size: .78rem;
  color: rgba(255,255,255,.6);
}
.deal-card__timer-icon { width: 14px; height: 14px; color: #f87171; flex-shrink: 0; }
.deal-card__countdown { font-weight: 700; color: #f87171; font-variant-numeric: tabular-nums; }

.deal-card__footer { padding: 1rem 1.25rem; border-top: 1px solid rgba(255,255,255,.08); }
.deal-card__footer .btn--primary { width: 100%; }

/* ===== EDITORIAL ===== */
.editorial { background: var(--color-surface-alt); }
.editorial__grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}
.editorial__grid .article-card:first-child {
  grid-row: span 2;
  grid-column: span 1;
}

@media (max-width: 900px) {
  .editorial__grid {
    grid-template-columns: 1fr 1fr;
  }
  .editorial__grid .article-card:first-child {
    grid-row: span 1;
    grid-column: span 2;
  }
}

.article-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1.5px solid var(--color-border);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.article-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.article-card:focus-within {
  box-shadow: var(--shadow-lg);
}

.article-card__image {
  aspect-ratio: 16/9;
  background: var(--color-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  overflow: hidden;
  position: relative;
}
.article-card:first-child .article-card__image { aspect-ratio: 4/3; font-size: 6rem; }
.article-card__image-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.3), transparent);
}

.article-card__body {
  padding: 1.25rem 1.5rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: .6rem;
  flex: 1;
}
.article-card__tag {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: .2rem .6rem;
  background: rgba(233,69,96,.1);
  color: var(--color-accent);
  border-radius: 999px;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
}
.article-card__title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  color: var(--color-text);
  transition: color var(--transition);
}
.article-card:first-child .article-card__title { font-size: 1.25rem; }
.article-card__title a:hover { color: var(--color-accent); }
.article-card__title a:focus-visible { outline: 2px solid var(--color-accent); border-radius: 2px; }
.article-card__excerpt {
  font-size: .85rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.article-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: .75rem;
  border-top: 1px solid var(--color-border);
  margin-top: auto;
  font-size: .78rem;
  color: var(--color-text-muted);
}
.article-card__author { font-weight: 600; }
.article-card__read-more {
  font-size: .8rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  transition: gap var(--transition);
}
.article-card__read-more:hover { gap: .5rem; }
.article-card__read-more:focus-visible { outline: 2px solid var(--color-accent); border-radius: 2px; }

/* ===== BANNER ===== */
.promo-banner {
  background: linear-gradient(135deg, #e94560 0%, #c73652 100%);
  padding-block: 4rem;
}
.promo-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}
.promo-banner__text { color: #fff; }
.promo-banner__eyebrow {
  display: block;
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .12em;
  opacity: .75;
  margin-bottom: .4rem;
}
.promo-banner__title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -.03em;
}
.promo-banner__subtitle {
  font-size: .95rem;
  opacity: .8;
  margin-top: .5rem;
}

/* ===== FOOTER ===== */
.site-footer {
  background: var(--color-primary);
  color: rgba(255,255,255,.7);
  padding-block: 4rem 2rem;
}
.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,.1);
}
.footer__brand-logo {
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: -.04em;
  color: #fff;
  margin-bottom: 1rem;
}
.footer__brand-logo span { color: var(--color-accent); }
.footer__brand-desc { font-size: .875rem; line-height: 1.7; max-width: 280px; }
.footer__socials {
  display: flex;
  gap: .5rem;
  margin-top: 1.5rem;
}
.footer__social-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,.08);
  color: rgba(255,255,255,.7);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .75rem;
  font-weight: 700;
  transition: background var(--transition), color var(--transition);
}
.footer__social-btn:hover { background: var(--color-accent); color: #fff; }
.footer__social-btn:focus-visible { outline: 2px solid var(--color-accent); }
.footer__col-title {
  font-size: .8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: #fff;
  margin-bottom: 1.25rem;
}
.footer__links { display: flex; flex-direction: column; gap: .65rem; }
.footer__link {
  font-size: .875rem;
  transition: color var(--transition);
}
.footer__link:hover { color: #fff; }
.footer__link:focus-visible { outline: 2px solid var(--color-accent); border-radius: 2px; }
.footer__bottom {
  padding-top: 1.75rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: .8rem;
}
.footer__legal { display: flex; gap: 1.25rem; }
.footer__legal a { transition: color var(--transition); }
.footer__legal a:hover { color: #fff; }

/* ===== CART DRAWER ===== */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity 250ms ease;
}
.cart-overlay.is-open {
  opacity: 1;
  pointer-events: all;
}
.cart-drawer {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: min(420px, 100vw);
  background: var(--color-surface);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 300ms cubic-bezier(.4,0,.2,1);
  box-shadow: var(--shadow-lg);
}
.cart-drawer.is-open { transform: translateX(0); }

.cart-drawer__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--color-border);
}
.cart-drawer__title { font-size: 1.1rem; font-weight: 800; }
.cart-drawer__close { color: var(--color-text-muted); transition: color var(--transition); }
.cart-drawer__close:hover { color: var(--color-accent); }
.cart-drawer__close:focus-visible { outline: 2px solid var(--color-accent); border-radius: var(--radius-sm); }
.cart-drawer__close svg { width: 22px; height: 22px; }

.cart-drawer__body { flex: 1; overflow-y: auto; padding: 1rem 1.5rem; }
.cart-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 1rem;
  text-align: center;
  color: var(--color-text-muted);
}
.cart-empty__icon { font-size: 4rem; }
.cart-empty__text { font-size: .9rem; }

.cart-item {
  display: flex;
  gap: 1rem;
  padding: 1rem 0;
  border-bottom: 1px solid var(--color-border);
  align-items: flex-start;
}
.cart-item__emoji {
  width: 64px; height: 64px;
  background: var(--color-surface-alt);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  flex-shrink: 0;
}
.cart-item__info { flex: 1; min-width: 0; }
.cart-item__name { font-size: .9rem; font-weight: 600; }
.cart-item__price { font-size: .85rem; color: var(--color-text-muted); margin-top: .2rem; }
.cart-item__remove { font-size: .75rem; color: var(--color-accent); font-weight: 600; margin-top: .4rem; display: inline-block; cursor: pointer; }
.cart-item__remove:hover { text-decoration: underline; }
.cart-item__qty {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: .5rem;
}
.cart-item__qty-btn {
  width: 24px; height: 24px;
  border-radius: 50%;
  background: var(--color-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 700;
  transition: background var(--transition);
}
.cart-item__qty-btn:hover { background: var(--color-border); }
.cart-item__qty-val { font-size: .875rem; font-weight: 700; min-width: 1.5ch; text-align: center; }
.cart-item__subtotal { font-size: .95rem; font-weight: 700; flex-shrink: 0; }

.cart-drawer__footer {
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--color-border);
}
.cart-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 1rem;
}
.cart-total__label { font-size: .9rem; color: var(--color-text-muted); }
.cart-total__value { font-size: 1.4rem; font-weight: 900; letter-spacing: -.03em; }
.cart-drawer__checkout { width: 100%; padding: 1rem; font-size: 1rem; }

/* ===== TOAST ===== */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 300;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .85rem 1.25rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: .875rem;
  font-weight: 500;
  min-width: 220px;
  max-width: 320px;
  transform: translateX(120%);
  opacity: 0;
  transition: transform 300ms cubic-bezier(.4,0,.2,1), opacity 300ms ease;
  pointer-events: all;
}
.toast.is-visible {
  transform: translateX(0);
  opacity: 1;
}
.toast__icon { font-size: 1.1rem; flex-shrink: 0; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero__content { grid-template-columns: 1fr; gap: 2.5rem; }
  .hero__visual { display: none; }
  .footer__grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
}

@media (max-width: 768px) {
  section { padding-block: 3.5rem; }
  .nav__links, .nav__search { display: none; }
  .nav__mobile-toggle { display: flex; align-items: center; justify-content: center; margin-left: auto; }
  .products__grid { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 1rem; }
  .deals__grid { grid-template-columns: 1fr; }
  .editorial__grid { grid-template-columns: 1fr; }
  .editorial__grid .article-card:first-child { grid-column: span 1; }
  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__brand { grid-column: 1 / -1; }
  .hero__stats { gap: 1.25rem; }
  .promo-banner__inner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .footer__grid { grid-template-columns: 1fr; }
  .footer__bottom { flex-direction: column; text-align: center; }
  .nav__logo { font-size: 1.2rem; }
}

/* ===== FOCUS VISIBLE GLOBAL ===== */
:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}
/* Remove outline from non-keyboard focuses */
:focus:not(:focus-visible) { outline: none; }

/* ===== REDUCED MOTION ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}
