  { id: 12, name: 'Standing Desk Converter',    meta: 'Height-adjustable, ergonomic', price: 119.0, originalPrice: 220.0, emoji: '🖥️', discount: '46% OFF', endsIn: 3600 * 22 },
];

const ARTICLES = [
  {
    title: 'The 2025 Gift Guide: Something for Everyone',
    tag: 'Gift Guide',
    excerpt: 'Struggling to find the perfect present? Our editors have curated over 50 thoughtful picks across every budget — from stocking stuffers to splurges that will genuinely surprise.',
    author: 'Sarah Lim',
    date: 'May 2, 2025',
    emoji: '🎁',
  },
  {
    title: 'How to Build a Capsule Wardrobe That Actually Works',
    tag: 'Style',
    excerpt: 'Less is more — especially when every piece earns its place.',
    author: 'James Park',
    date: 'Apr 28, 2025',
    emoji: '👔',
  },
  {
    title: 'Home Upgrades Under $50',
    tag: 'Home',
    excerpt: 'Small swaps that make a big difference.',
    author: 'Mia Torres',
    date: 'Apr 22, 2025',
    emoji: '🏠',
  },
  {
    title: 'The Best Running Gear for Every Level',
    tag: 'Sport',
