// ===== CART STATE =====
let cart = [];

function cartCount() {
  return cart.reduce((sum, item) => sum + item.qty, 0);
}
function cartSubtotal() {
  return cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function addToCart(product) {
  const existing = cart.find(i => i.id === product.id);
  if (existing) {
    existing.qty += 1;
  } else {
    cart.push({ ...product, qty: 1 });
  }
  updateCartUI();
  showToast(`${product.emoji} ${product.name} added to cart`);
}

function removeFromCart(productId) {
  cart = cart.filter(i => i.id !== productId);
  updateCartUI();
}

function updateQty(productId, delta) {
  const item = cart.find(i => i.id === productId);
  if (!item) return;
  item.qty = Math.max(0, item.qty + delta);
  if (item.qty === 0) removeFromCart(productId);
  else updateCartUI();
}

// ===== UI RENDERERS =====
function renderCategories() {
  const grid = document.getElementById('categories-grid');
  if (!grid) return;
  grid.innerHTML = CATEGORIES.map(cat => `
    <li>
      <a href="#" class="category-card" aria-label="${cat.name} — ${cat.count} products">
        <span class="category-card__icon" aria-hidden="true">${cat.icon}</span>
        <span class="category-card__name">${cat.name}</span>
        <span class="category-card__count">${cat.count} items</span>
      </a>
    </li>
  `).join('');
}

function renderProducts() {
  const grid = document.getElementById('products-grid');
  if (!grid) return;
  grid.innerHTML = FEATURED_PRODUCTS.map(p => {
    const badge = p.badge
      ? `<span class="product-card__badge product-card__badge--${p.badge}">${p.badge === 'bestseller' ? '⭐ Best Seller' : p.badge === 'new' ? '✦ New' : '🔖 Sale'}</span>`
      : '';
    const origPrice = p.originalPrice
      ? `<span class="product-card__price-original" aria-label="Was $${p.originalPrice.toFixed(2)}">$${p.originalPrice.toFixed(2)}</span>`
      : '';
    const savings = p.originalPrice
      ? ` <span class="visually-hidden">(Save $${(p.originalPrice - p.price).toFixed(2)})</span>`
      : '';
    return `
      <li>
        <article class="product-card" aria-label="${p.name}">
          <div class="product-card__image-wrap">
            <span class="product-card__emoji" role="img" aria-label="${p.category} product">${p.emoji}</span>
            ${badge}
            <div class="product-card__actions" role="group" aria-label="Quick actions for ${p.name}">
              <button class="btn btn--icon" aria-label="Add ${p.name} to wishlist" data-action="wishlist" data-id="${p.id}">
                <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg>
              </button>
              <button class="btn btn--icon" aria-label="Quick view ${p.name}" data-action="quickview" data-id="${p.id}">
                <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
              </button>
            </div>
          </div>
          <div class="product-card__body">
            <span class="product-card__category">${p.category}</span>
            <h3 class="product-card__name">${p.name}</h3>
            <div class="product-card__rating" aria-label="Rated ${p.rating} out of 5, ${p.reviews.toLocaleString()} reviews">
              <span class="product-card__stars" aria-hidden="true">${starsHtml(p.rating)}</span>
              <span>${p.rating}</span>
              <span>(${p.reviews.toLocaleString()})</span>
            </div>
          </div>
          <div class="product-card__footer">
            <div class="product-card__price-group">
              <span class="product-card__price">$${p.price.toFixed(2)}${savings}</span>
              ${origPrice}
            </div>
            <button class="product-card__add-btn" data-action="add-to-cart" data-id="${p.id}" aria-label="Add ${p.name} to cart, $${p.price.toFixed(2)}">
              <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M12 4v16m8-8H4"/></svg>
              Add
            </button>
          </div>
        </article>
      </li>
    `;
  }).join('');
}

function starsHtml(rating) {
  const full = Math.floor(rating);
  const half = rating % 1 >= 0.5 ? 1 : 0;
  return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(5 - full - half);
}

function renderDeals() {
  const grid = document.getElementById('deals-grid');
  if (!grid) return;
  grid.innerHTML = DEALS.map(d => {
    const savings = (d.originalPrice - d.price).toFixed(2);
    return `
      <li>
        <article class="deal-card" aria-label="${d.name} deal">
          <div class="deal-card__image-wrap" role="img" aria-label="${d.name}">
            <span aria-hidden="true">${d.emoji}</span>
            <span class="deal-card__discount" aria-label="${d.discount} discount">${d.discount}</span>
          </div>
          <div class="deal-card__body">
            <h3 class="deal-card__name">${d.name}</h3>
            <p class="deal-card__meta">${d.meta}</p>
            <div class="deal-card__pricing">
              <span class="deal-card__price-new" aria-label="Sale price $${d.price.toFixed(2)}">$${d.price.toFixed(2)}</span>
              <span class="deal-card__price-old" aria-label="Original price $${d.originalPrice.toFixed(2)}">$${d.originalPrice.toFixed(2)}</span>
              <span class="deal-card__savings" aria-label="You save $${savings}">Save $${savings}</span>
            </div>
          </div>
          <div class="deal-card__timer" aria-live="polite" aria-label="Deal ends in">
            <svg class="deal-card__timer-icon" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
            <span>Ends in </span>
            <span class="deal-card__countdown" data-ends-in="${d.endsIn}" aria-label="countdown">--:--:--</span>
          </div>
          <div class="deal-card__footer">
            <button class="btn btn--primary deal-card__buy-btn" data-action="add-to-cart" data-id="${d.id}" aria-label="Add ${d.name} to cart at sale price $${d.price.toFixed(2)}">
              <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" style="width:16px;height:16px"><path stroke-linecap="round" stroke-linejoin="round" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
              Grab This Deal
            </button>
          </div>
        </article>
      </li>
    `;
  }).join('');
}

function renderEditorial() {
  const grid = document.getElementById('editorial-grid');
  if (!grid) return;
  grid.innerHTML = ARTICLES.map((a, i) => `
    <li>
      <article class="article-card" aria-label="${a.title}">
        <div class="article-card__image" role="img" aria-label="${a.title} cover image">
          <span aria-hidden="true">${a.emoji}</span>
          <div class="article-card__image-overlay" aria-hidden="true"></div>
        </div>
        <div class="article-card__body">
          <span class="article-card__tag">${a.tag}</span>
          <h3 class="article-card__title">
            <a href="#" aria-label="Read article: ${a.title}">${a.title}</a>
          </h3>
          <p class="article-card__excerpt">${a.excerpt}</p>
          <div class="article-card__footer">
            <span class="article-card__author">${a.author} · <time>${a.date}</time></span>
            <a href="#" class="article-card__read-more" aria-label="Read more: ${a.title}">
              Read more
              <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" style="width:13px;height:13px"><path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/></svg>
            </a>
          </div>
        </div>
      </article>
    </li>
  `).join('');
}

// ===== CART UI =====
function updateCartUI() {
  // Badge
  const badge = document.getElementById('cart-badge');
  const count = cartCount();
  badge.textContent = count;
  badge.hidden = count === 0;

  // Drawer items
  const body = document.getElementById('cart-body');
  if (cart.length === 0) {
    body.innerHTML = `
      <div class="cart-empty" role="status" aria-label="Your cart is empty">
        <span class="cart-empty__icon" aria-hidden="true">🛒</span>
        <p class="cart-empty__text">Your cart is empty.<br>Add something to get started!</p>
      </div>`;
  } else {
    body.innerHTML = cart.map(item => `
      <div class="cart-item" role="listitem">
        <div class="cart-item__emoji" role="img" aria-label="${item.name}">${item.emoji}</div>
        <div class="cart-item__info">
          <div class="cart-item__name">${item.name}</div>
          <div class="cart-item__price">$${item.price.toFixed(2)} each</div>
          <div class="cart-item__qty" role="group" aria-label="Quantity for ${item.name}">
            <button class="cart-item__qty-btn" data-cart-qty="${item.id}" data-delta="-1" aria-label="Decrease quantity for ${item.name}">−</button>
            <span class="cart-item__qty-val" aria-label="Quantity: ${item.qty}">${item.qty}</span>
            <button class="cart-item__qty-btn" data-cart-qty="${item.id}" data-delta="1" aria-label="Increase quantity for ${item.name}">+</button>
          </div>
          <button class="cart-item__remove" data-cart-remove="${item.id}" aria-label="Remove ${item.name} from cart">Remove</button>
        </div>
        <div class="cart-item__subtotal" aria-label="Subtotal for ${item.name}: $${(item.price * item.qty).toFixed(2)}">$${(item.price * item.qty).toFixed(2)}</div>
      </div>
    `).join('');
  }

  // Total
  document.getElementById('cart-total').textContent = `$${cartSubtotal().toFixed(2)}`;
}

// ===== CART DRAWER =====
function openCart() {
  const overlay = document.getElementById('cart-overlay');
  const drawer  = document.getElementById('cart-drawer');
  overlay.classList.add('is-open');
  drawer.classList.add('is-open');
  drawer.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
  document.getElementById('cart-close').focus();
}

function closeCart() {
  const overlay = document.getElementById('cart-overlay');
  const drawer  = document.getElementById('cart-drawer');
  overlay.classList.remove('is-open');
  drawer.classList.remove('is-open');
  drawer.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
  document.getElementById('cart-btn').focus();
}

// ===== TOAST =====
function showToast(message) {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');
  toast.innerHTML = `<span class="toast__icon" aria-hidden="true">✓</span><span>${message}</span>`;
  container.appendChild(toast);
  requestAnimationFrame(() => {
    requestAnimationFrame(() => toast.classList.add('is-visible'));
  });
  setTimeout(() => {
    toast.classList.remove('is-visible');
    toast.addEventListener('transitionend', () => toast.remove(), { once: true });
  }, 3200);
}

// ===== COUNTDOWN TIMERS =====
function startCountdowns() {
  const endTimes = {};
  document.querySelectorAll('.deal-card__countdown').forEach(el => {
    const secs = parseInt(el.dataset.endsIn, 10);
    endTimes[el.dataset.endsIn + Math.random()] = { el, end: Date.now() + secs * 1000 };
  });

  const timers = Array.from(document.querySelectorAll('.deal-card__countdown')).map(el => ({
    el,
    end: Date.now() + parseInt(el.dataset.endsIn, 10) * 1000,
  }));

  function tick() {
    const now = Date.now();
    timers.forEach(({ el, end }) => {
      const diff = Math.max(0, Math.floor((end - now) / 1000));
      const h = String(Math.floor(diff / 3600)).padStart(2, '0');
      const m = String(Math.floor((diff % 3600) / 60)).padStart(2, '0');
      const s = String(diff % 60).padStart(2, '0');
      el.textContent = `${h}:${m}:${s}`;
      el.setAttribute('aria-label', `${h} hours ${m} minutes ${s} seconds remaining`);
    });
    requestAnimationFrame(tick);
  }
  tick();
}

// ===== PRODUCT LOOKUP =====
const ALL_PRODUCTS = [...FEATURED_PRODUCTS, ...DEALS.map(d => ({ ...d, rating: 4.5, reviews: 0, category: 'Deals' }))];
function findProduct(id) {
  return ALL_PRODUCTS.find(p => p.id === parseInt(id, 10));
}

// ===== EVENT DELEGATION =====
function initEvents() {
  // Unified click handler
  document.addEventListener('click', e => {
    const btn = e.target.closest('[data-action]');
    if (btn) {
      const action = btn.dataset.action;
      const id     = btn.dataset.id;
      if (action === 'add-to-cart') {
        const p = findProduct(id);
        if (p) addToCart(p);
      } else if (action === 'wishlist') {
        showToast('❤️ Added to your wishlist!');
      } else if (action === 'quickview') {
        showToast('🔍 Quick view coming soon!');
      }
    }

    // Cart qty
    const qtyBtn = e.target.closest('[data-cart-qty]');
    if (qtyBtn) {
      updateQty(parseInt(qtyBtn.dataset.cartQty, 10), parseInt(qtyBtn.dataset.delta, 10));
    }

    // Cart remove
    const removeBtn = e.target.closest('[data-cart-remove]');
    if (removeBtn) {
      removeFromCart(parseInt(removeBtn.dataset.cartRemove, 10));
    }

    // Cart open
    if (e.target.closest('#cart-btn')) openCart();

    // Cart close
    if (e.target.closest('#cart-close')) closeCart();
    if (e.target.closest('#cart-overlay') && !e.target.closest('#cart-drawer')) closeCart();
  });

  // Keyboard trap in cart drawer
  document.getElementById('cart-drawer').addEventListener('keydown', e => {
    if (e.key !== 'Tab') return;
    const focusable = Array.from(
      document.getElementById('cart-drawer').querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      )
    ).filter(el => !el.disabled);
    if (!focusable.length) return;
    const first = focusable[0], last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault(); last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault(); first.focus();
    }
  });

  // Escape closes cart
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeCart();
  });
}

// ===== INIT =====
document.addEventListener('DOMContentLoaded', () => {
  renderCategories();
  renderProducts();
  renderDeals();
  renderEditorial();
  updateCartUI();
  initEvents();
  startCountdowns();
});

