  drawer.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
  document.getElementById('cart-close').focus();
}

function closeCart() {
  const overlay = document.getElementById('cart-overlay');
  const drawer  = document.getElementById('cart-drawer');
  overlay.classList.remove('is-open');
  drawer.classList.remove('is-open');
  drawer.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
  document.getElementById('cart-btn').focus();
}

// ===== TOAST =====
function showToast(message) {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');
  toast.innerHTML = `<span class="toast__icon" aria-hidden="true">✓</span><span>${message}</span>`;
  container.appendChild(toast);
  requestAnimationFrame(() => {
    requestAnimationFrame(() => toast.classList.add('is-visible'));
  });
  setTimeout(() => {
    toast.classList.remove('is-visible');
    toast.addEventListener('transitionend', () => toast.remove(), { once: true });
  }, 3200);
}

// ===== COUNTDOWN TIMERS =====
function startCountdowns() {
  const endTimes = {};
  document.querySelectorAll('.deal-card__countdown').forEach(el => {
    const secs = parseInt(el.dataset.endsIn, 10);
    endTimes[el.dataset.endsIn + Math.random()] = { el, end: Date.now() + secs * 1000 };
  });

  const timers = Array.from(document.querySelectorAll('.deal-card__countdown')).map(el => ({
    el,
    end: Date.now() + parseInt(el.dataset.endsIn, 10) * 1000,
  }));

  function tick() {
    const now = Date.now();
    timers.forEach(({ el, end }) => {
      const diff = Math.max(0, Math.floor((end - now) / 1000));
      const h = String(Math.floor(diff / 3600)).padStart(2, '0');
      const m = String(Math.floor((diff % 3600) / 60)).padStart(2, '0');
      const s = String(diff % 60).padStart(2, '0');
      el.textContent = `${h}:${m}:${s}`;
      el.setAttribute('aria-label', `${h} hours ${m} minutes ${s} seconds remaining`);
    });
    requestAnimationFrame(tick);
  }
  tick();
}

