+      <div class="cart-empty" role="status" aria-label="Your cart is empty">
+        <span class="cart-empty__icon" aria-hidden="true">🛒</span>
+        <p class="cart-empty__text">Your cart is empty.<br>Add something to get started!</p>
+      </div>`;
+  } else {
+    body.innerHTML = cart.map(item => `
+      <div class="cart-item" role="listitem">
+        <div class="cart-item__emoji" role="img" aria-label="${item.name}">${item.emoji}</div>
+        <div class="cart-item__info">
+          <div class="cart-item__name">${item.name}</div>
+          <div class="cart-item__price">$${item.price.toFixed(2)} each</div>
+          <div class="cart-item__qty" role="group" aria-label="Quantity for ${item.name}">
+            <button class="cart-item__qty-btn" data-cart-qty="${item.id}" data-delta="-1" aria-label="Decrease quantity for ${item.name}">−</button>
+            <span class="cart-item__qty-val" aria-label="Quantity: ${item.qty}">${item.qty}</span>
+            <button class="cart-item__qty-btn" data-cart-qty="${item.id}" data-delta="1" aria-label="Increase quantity for ${item.name}">+</button>
+          </div>
+          <button class="cart-item__remove" data-cart-remove="${item.id}" aria-label="Remove ${item.name} from cart">Remove</button>
+        </div>
+        <div class="cart-item__subtotal" aria-label="Subtotal for ${item.name}: $${(item.price * item.qty).toFixed(2)}">$${(item.price * item.qty).toFixed(2)}</div>
+      </div>
+    `).join('');
+  }
+
+  // Total
+  document.getElementById('cart-total').textContent = `$${cartSubtotal().toFixed(2)}`;
+}
+
+// ===== CART DRAWER =====
+function openCart() {
+  const overlay = document.getElementById('cart-overlay');
+  const drawer  = document.getElementById('cart-drawer');
+  overlay.classList.add('is-open');
+  drawer.classList.add('is-open');
+  drawer.setAttribute('aria-hidden', 'false');
+  document.body.style.overflow = 'hidden';
+  document.getElementById('cart-close').focus();
+}
+
+function closeCart() {
+  const overlay = document.getElementById('cart-overlay');
+  const drawer  = document.getElementById('cart-drawer');
+  overlay.classList.remove('is-open');
+  drawer.classList.remove('is-open');
+  drawer.setAttribute('aria-hidden', 'true');
+  document.body.style.overflow = '';
+  document.getElementById('cart-btn').focus();
+}
+
+// ===== TOAST =====
+function showToast(message) {
+  const container = document.getElementById('toast-container');
+  const toast = document.createElement('div');
+  toast.className = 'toast';
+  toast.setAttribute('role', 'status');
+  toast.setAttribute('aria-live', 'polite');
+  toast.innerHTML = `<span class="toast__icon" aria-hidden="true">✓</span><span>${message}</span>`;
+  container.appendChild(toast);
+  requestAnimationFrame(() => {
+    requestAnimationFrame(() => toast.classList.add('is-visible'));
+  });
+  setTimeout(() => {
+    toast.classList.remove('is-visible');
+    toast.addEventListener('transitionend', () => toast.remove(), { once: true });
+  }, 3200);
+}
+
+// ===== COUNTDOWN TIMERS =====
+function startCountdowns() {
+  const endTimes = {};
+  document.querySelectorAll('.deal-card__countdown').forEach(el => {
+    const secs = parseInt(el.dataset.endsIn, 10);
+    endTimes[el.dataset.endsIn + Math.random()] = { el, end: Date.now() + secs * 1000 };
+  });
+
+  const timers = Array.from(document.querySelectorAll('.deal-card__countdown')).map(el => ({
+    el,
+    end: Date.now() + parseInt(el.dataset.endsIn, 10) * 1000,
+  }));
+
+  function tick() {
+    const now = Date.now();
+    timers.forEach(({ el, end }) => {
+      const diff = Math.max(0, Math.floor((end - now) / 1000));
+      const h = String(Math.floor(diff / 3600)).padStart(2, '0');
+      const m = String(Math.floor((diff % 3600) / 60)).padStart(2, '0');
+      const s = String(diff % 60).padStart(2, '0');
+      el.textContent = `${h}:${m}:${s}`;
+      el.setAttribute('aria-label', `${h} hours ${m} minutes ${s} seconds remaining`);
+    });
+    requestAnimationFrame(tick);
+  }
+  tick();
+}
+
+// ===== PRODUCT LOOKUP =====
+const ALL_PRODUCTS = [...FEATURED_PRODUCTS, ...DEALS.map(d => ({ ...d, rating: 4.5, reviews: 0, category: 'Deals' }))];
+function findProduct(id) {
+  return ALL_PRODUCTS.find(p => p.id === parseInt(id, 10));
+}
+
+// ===== EVENT DELEGATION =====
+function initEvents() {
+  // Unified click handler
+  document.addEventListener('click', e => {
+    const btn = e.target.closest('[data-action]');
+    if (btn) {
+      const action = btn.dataset.action;
+      const id     = btn.dataset.id;
+      if (action === 'add-to-cart') {
+        const p = findProduct(id);
+        if (p) addToCart(p);
+      } else if (action === 'wishlist') {
+        showToast('❤️ Added to your wishlist!');
+      } else if (action === 'quickview') {
+        showToast('🔍 Quick view coming soon!');
+      }
+    }
+
+    // Cart qty
+    const qtyBtn = e.target.closest('[data-cart-qty]');
+    if (qtyBtn) {
+      updateQty(parseInt(qtyBtn.dataset.cartQty, 10), parseInt(qtyBtn.dataset.delta, 10));
+    }
+
+    // Cart remove
+    const removeBtn = e.target.closest('[data-cart-remove]');
+    if (removeBtn) {
+      removeFromCart(parseInt(removeBtn.dataset.cartRemove, 10));
+    }
+
+    // Cart open
+    if (e.target.closest('#cart-btn')) openCart();
+
+    // Cart close
+    if (e.target.closest('#cart-close')) closeCart();
+    if (e.target.closest('#cart-overlay') && !e.target.closest('#cart-drawer')) closeCart();
+  });
+
+  // Keyboard trap in cart drawer
+  document.getElementById('cart-drawer').addEventListener('keydown', e => {
+    if (e.key !== 'Tab') return;
+    const focusable = Array.from(
+      document.getElementById('cart-drawer').querySelectorAll(
+        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
+      )
+    ).filter(el => !el.disabled);
+    if (!focusable.length) return;
+    const first = focusable[0], last = focusable[focusable.length - 1];
+    if (e.shiftKey && document.activeElement === first) {
+      e.preventDefault(); last.focus();
+    } else if (!e.shiftKey && document.activeElement === last) {
+      e.preventDefault(); first.focus();
+    }
+  });
+
+  // Escape closes cart
+  document.addEventListener('keydown', e => {
+    if (e.key === 'Escape') closeCart();
+  });
+}
+
+// ===== INIT =====
+document.addEventListener('DOMContentLoaded', () => {
+  renderCategories();
+  renderProducts();
+  renderDeals();
+  renderEditorial();
+  updateCartUI();
+  initEvents();
+  startCountdowns();
+});
+
')

